436	/// One fully-aggregated model turn.
437	///
438	/// Reassembled from a [`ModelEvent`] stream by [`ModelTurnAccumulator`]: the
439	/// concatenated text/reasoning deltas become at most one
440	/// [`crate::Item::AssistantMessage`], each distinct `ToolCallDelta` `call_id`
441	/// becomes one [`crate::Item::ToolCall`], `usage` is the last `Usage`
442	/// snapshot observed, and `finish_reason` is the terminal `Finish` reason.
443	#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
444	#[non_exhaustive]
445	pub struct ModelTurn {
446	    /// Reconstructed items: an optional leading `AssistantMessage` (text
447	    /// and/or reasoning content) followed by zero or more `ToolCall`s, in
448	    /// deterministic `call_id`-sorted order.
449	    pub items: Vec<crate::Item>,
450	    /// The last [`ModelEvent::Usage`] snapshot observed (last-wins; usage
451	    /// snapshots are never summed within a turn), or the zero default if
452	    /// the stream never emitted one.
453	    pub usage: crate::TokenUsage,
454	    /// Why the response ended.
455	    pub finish_reason: FinishReason,
456	}
457	
458	impl ModelTurn {
459	    /// Construct a `ModelTurn` directly from its parts.
460	    ///
461	    /// The normal path is [`ModelTurnAccumulator::finish`], which reassembles
462	    /// a turn from a live [`ModelEvent`] stream. This constructor is for
463	    /// callers that already have `items`/`usage`/`finish_reason` in hand —
464	    /// durable-runner activities that reconstruct a turn from a stored
465	    /// result, and tests — and would otherwise be unable to build one at all
466	    /// (`#[non_exhaustive]` blocks struct-literal construction outside this
467	    /// crate).
468	    pub fn new(
469	        items: Vec<crate::Item>,
470	        usage: crate::TokenUsage,
471	        finish_reason: FinishReason,
472	    ) -> Self {
473	        Self {
474	            items,
475	            usage,
476	            finish_reason,
477	        }
478	    }
479	}
