210	///
211	/// - `response.output_text.delta` → `TokenDelta`
212	/// - `response.refusal.delta` → `TokenDelta` (refusal is the model's text)
213	/// - `response.reasoning_summary_text.delta` → `ReasoningDelta`
214	/// - `response.reasoning_text.delta` → `ReasoningDelta`
215	/// - `response.output_item.added` (when item is a function call) →
216	///   registers `item.id` → `(item.call_id, item.name)` for subsequent argument deltas;
217	///   also flushes any argument deltas that arrived before this event (out-of-order case).
218	/// - `response.function_call_arguments.delta` → `ToolCallDelta` with
219	///   name-emission gating (name emitted once per call_id, then `None`). If
220	///   `output_item.added` has not yet registered the item_id, the delta is buffered
221	///   in `pending_args` and flushed when the registration eventually arrives.
222	/// - `response.completed` → `Usage` + `Finish { Stop }`
223	/// - `response.incomplete` → `Usage` + `Finish` per `incomplete_details.reason`
224	///   - `"max_output_tokens"` → `Finish { Length }`
225	///   - `"content_filter"` → `Finish { ContentFilter }`
226	///   - other → `Finish { Other(reason) }`
227	/// - `response.failed` → `Err(ModelError)` on the outer stream
228	/// - `error` → `Err(ModelError)` on the outer stream
229	///
230	/// All other events are dropped with a `tracing::debug!` log.
231	///
232	/// ## id vs call_id
233	///
234	/// The Responses API distinguishes two identifiers on function-call items:
235	/// - `item.id` — internal item identifier; matches `function_call_arguments.delta.item_id`
236	///   and is used as the correlator between `OutputItemAdded` and subsequent delta events.
237	/// - `item.call_id` — stable identifier for tool submission; this is what downstream
238	///   consumers (tool runners, conversation history) must use when referencing the call.
239	///
240	/// `item_to_call` maps the internal `item_id` → `(call_id, name)` so that
241	/// `ToolCallDelta.call_id` always carries the stable call_id.
242	pub(crate) struct ResponsesTranslator {
243	    /// Tracks item_ids (internal correlator) for which a name has already been
244	    /// emitted (name-emission gating: name is `Some` on the first `ToolCallDelta`
245	    /// for a given item_id, then `None` on subsequent deltas).
246	    name_emitted: HashSet<String>,
247	    /// Maps internal `item_id` → `(stable call_id, function name)`.
248	    ///
249	    /// Populated by `response.output_item.added` when the item is a function call.
250	    /// Keyed by `item.id` (the correlator used in `function_call_arguments.delta`),
251	    /// not by `item.call_id` (the stable downstream identifier).
252	    item_to_call: HashMap<String, (String, String)>,
253	    /// Buffered argument deltas that arrived (via `function_call_arguments.delta`)
254	    /// before `output_item.added` registered the corresponding `item_id` mapping.
255	    ///
256	    /// Keyed by `item_id`. Flushed as a single `ToolCallDelta` (with the real
257	    /// `call_id` and `name`) the moment `output_item.added` registers the item.
258	    pending_args: HashMap<String, String>,
259	}
